import json, os, socket, subprocess, signal, tempfile

report = {}

def safe(fn, default=None):
    try:
        return fn()
    except Exception as e:
        return default

# --- egress_http: fetch https://example.com with a timeout ---
def probe_http():
    try:
        r = subprocess.run(
            ["curl", "-sS", "-o", "/dev/null", "-w", "%{http_code}",
             "--max-time", "12", "https://example.com"],
            capture_output=True, text=True, timeout=15,
        )
        code = r.stdout.strip()
        return r.returncode == 0 and code.startswith("2")
    except Exception:
        return False
report["egress_http"] = safe(probe_http, False)

# --- dns: name resolution for example.com (separate from TCP) ---
class Timeout(Exception):
    pass

def _alarm(signum, frame):
    raise Timeout()

def probe_dns():
    old = signal.signal(signal.SIGALRM, _alarm)
    signal.alarm(8)
    try:
        socket.getaddrinfo("example.com", 443,
                           proto=socket.IPPROTO_TCP)
        return True
    except Exception:
        return False
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old)
report["dns"] = safe(probe_dns, False)

# --- uid ---
report["uid"] = safe(lambda: os.getuid(), -1)

# --- engine_sockets: control sockets present ---
CANDIDATES = [
    "/var/run/docker.sock",
    "/run/podman/podman.sock",
    "/run/docker.sock",
    "/var/run/podman/podman.sock",
]
def probe_sockets():
    found = []
    for p in CANDIDATES:
        try:
            if os.path.exists(p):
                found.append(p)
        except OSError:
            pass
    return found
report["engine_sockets"] = safe(probe_sockets, [])

# --- writable_workdir ---
def probe_writable(d):
    try:
        fd, path = tempfile.mkstemp(dir=d, prefix=".probe_")
        os.close(fd)
        os.unlink(path)
        return True
    except Exception:
        return False
report["writable_workdir"] = safe(lambda: probe_writable("/app"), False)

# --- writable_tmp ---
report["writable_tmp"] = safe(lambda: probe_writable("/tmp"), False)

# --- sysrq_writable: actually attempt, flush + close so errors surface ---
def probe_sysrq():
    try:
        with open("/proc/sysrq-trigger", "w") as f:
            f.write("h")
            f.flush()
            os.fsync(f.fileno())
        return True
    except Exception:
        return False
report["sysrq_writable"] = safe(probe_sysrq, False)

# --- pid1_comm ---
def probe_pid1():
    with open("/proc/1/comm") as f:
        return f.read().strip()
report["pid1_comm"] = safe(probe_pid1, "")

# --- dmesg_gvisor ---
def probe_dmesg():
    r = subprocess.run(["dmesg"], capture_output=True, text=True, timeout=10)
    out = (r.stdout or "") + (r.stderr or "")
    if r.returncode != 0 and not out:
        return False
    return "gvisor" in out.lower()
report["dmesg_gvisor"] = safe(probe_dmesg, False)

# --- kernel_release ---
def probe_uname():
    r = subprocess.run(["uname", "-r"], capture_output=True, text=True, timeout=5)
    return r.stdout.strip()
report["kernel_release"] = safe(probe_uname, "")

with open("/app/report.json", "w") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

print(json.dumps(report, indent=2))
PYEOF
python3 /tmp/probe.py; echo "rc=$?"
